public static TFMProcessVersion Find(TFMProcessId _processId, Version _version = 0, boolean _selectForUpdate = false)
{
    TFMProcessVersion pVersion;

    pVersion.selectForUpdate(_selectForUpdate);

    select firstonly pVersion order by Version desc where pVersion.ProcessID == _processId && (pVersion.Version == _version || !_version);

    return pVersion;
}

public static TFMProcessVersion FindOrMake(TFMProcessId _processId, Version _version = 0, boolean _selectForUpdate = false)
{
    TFMProcessVersion pVersion = TFMProcessVersion::Find(_processId,_version,_selectForUpdate);
    if (!pVersion)
    {
        pVersion.ProcessID = _processId;
        pVersion.Version = _version;
        pVersion.selectForUpdate(_selectForUpdate);
    }
    return pVersion;
}

 public static void DeleteAll(TFMProcessId _processId)
 {
     TFMProcessVersion pVersion;
     delete_from pVersion where pVersion.ProcessID == _processId;

     TFMProcessBlocks::DeleteAllGenericParmsForBlocks(_processId);
}

public static TFMProcessVersion Increment(TFMProcessId _processId)
{
    TFMProcessVersion   pVersion;
    Version             versionOld;
    ttsbegin;
    pVersion = TFMProcessVersion::Find(_processId, 0, true);
    if (!pVersion.Locked && pVersion.Version)
    {
        ttsabort;
        warning("@TFM:Versionhasnotbeenlockedyoucanonl");
        return pVersion;
    }
    pVersion.ProcessID = _processId;
    versionOld = pVersion.Version;
    pVersion.Version += 1;
    pVersion.Locked = false;
    pVersion.insert();
    TFMProcessBlocks::versionIncrement(_processId,versionOld,pVersion.Version);
    ttscommit;
    return pVersion;
}

public static Version newestVersion(TFMProcessId _processId, boolean _newestLocked = false)
{
    TFMProcessVersion pVersion = TFMProcessVersion::newestProcessVersion(_processId, _newestLocked);
    if(!pVersion && pVersion.RecId)
    {
        return -1;
    }
    return pVersion.Version;
}

public static TFMProcessVersion newestProcessVersion(TFMProcessId _processId, boolean _newestLocked = false, boolean _selectForUpdate = false)
{
    TFMProcessVersion pVersion;
    if(_selectForUpdate)
    {
        select forupdate firstonly pVersion order by Version desc where pVersion.ProcessID == _processId && (pVersion.Locked || !_newestLocked);
    }
    else
    {
        select firstonly pVersion order by Version desc where pVersion.ProcessID == _processId && (pVersion.Locked || !_newestLocked);
    }
    return pVersion;
}

public static void lockVersion(TFMProcessId _processId)
{
    TFMProcessVersion pVersion = TFMProcessVersion::newestProcessVersion(_processId, false, true);
    if(pVersion)
    {
        ttsbegin;
        pVersion.Locked = true;
        pVersion.update();
        ttscommit;
    }
}

public display str sequence()
{
    TFMProcessBlockchainLinks   links;
    TFMProcessBlocks            blocks;
    str                         result;
    Map                         blockMap = new Map(Types::Int64, Types::Class);
    TFMBlockConnectionNode      node, toNode;
    List                        startingNodes = new List(Types::Class);
    ListEnumerator              lEnum;
    while select blocks where blocks.Version == this.Version && blocks.ProcessID == this.ProcessID
    {
        node = new TFMBlockConnectionNode();
        node.parmData(blocks.BlockClass);
        blockMap.insert(blocks.RecId, node);
    }

    while select blocks where blocks.Version == this.Version && blocks.ProcessID == this.ProcessID
        join links where links.FromBlock == blocks.RecId
    {
        node = blockMap.lookup(links.FromBlock);
        toNode = blockMap.lookup(links.ToBlock);
        node.addToLink(toNode,links.FromName, links.toName);
    }
    if (!node)
    {
        return '';
    }
    node.findStartingNodes(startingNodes);
    lEnum = startingNodes.getEnumerator();
    while (lEnum.moveNext())
    {
        node = lEnum.current();
        result += this.printGraph(node) + TFMConstants::lineBreak();

    }
    return result;
}

public str printGraph(TFMBlockConnectionNode _node, int _depth = 0)
{
    ListEnumerator          lEnum = _node.getToLinks().getEnumerator();
    str                     ret = _node.parmData() + '--';
    TFMBlockConnectionNode  childNode;

    while (lEnum.moveNext())
    {
        childNode = lEnum.current();
        ret += this.printGraph(childNode, _depth + 1);
    }
    return ret;
}
